function Run-Step($name, $file, $cfg, $mins) {
  $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
  $out = "logs\retry-$name-out-$stamp.log"
  $err = "logs\retry-$name-err-$stamp.log"
  Write-Host "==== START $name cfg=$cfg out=$out ===="
  $args = @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',$file,'-ConfigPath',(Resolve-Path $cfg).Path)
  if ($file -match 'run-products|run-orders|run-shop') { $args += @('-DryRun','false') }
  $p = Start-Process -FilePath powershell.exe -ArgumentList $args -WorkingDirectory (Get-Location).Path -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err
  $deadline = (Get-Date).AddMinutes($mins)
  while ((Get-Date) -lt $deadline -and -not $p.HasExited) {
    Start-Sleep -Seconds 30
    $sz = if (Test-Path $out) { (Get-Item $out).Length } else { 0 }
    $last = if (Test-Path $out) { (Get-Content $out -Tail 1 -Encoding UTF8) } else { '' }
    Write-Host ("[{0}] {1} size={2} | {3}" -f (Get-Date -Format HH:mm:ss), $name, $sz, $last)
  }
  if (-not $p.HasExited) {
    Write-Host "TIMEOUT $name killing"
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
    return @{ name=$name; code=-1; out=$out }
  }
  Write-Host "END $name exit=$($p.ExitCode)"
  Get-Content $out -Tail 25 -Encoding UTF8 | ForEach-Object { Write-Host $_ }
  return @{ name=$name; code=$p.ExitCode; out=$out }
}

