  $warmJs = 'JSON.stringify({ok:true,href:String(location.href||""),tables:document.querySelectorAll("table").length,tlen:((document.body&&document.body.innerText)||"").length})'
  $href = ''
  $tables = 0
  $tlen = 0
  $warmOk = $false
  $maxWarm = 8
  for ($wi = 1; $wi -le $maxWarm; $wi++) {
    [void](Wait-ZiniaoBridgeReady -MaxSec 20)
    $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
