1	# TikTok products multi-store scrape (P2b skeleton) via ziniao-cli
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1 -ListOnly
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1 -DryRun true
6	#
7	# Requires: Ziniao client + Bridge; config\stores.config.json
8	# Does NOT write Feishu by default (products Feishu optional later) — only Qingquan ingest.
9	
10	param(
11	  [string]$ConfigPath = "",
12	  [switch]$ListOnly,
13	  [string]$DryRun = ""
14	)
15	
16	$ErrorActionPreference = 'Stop'
17	$PSNativeCommandUseErrorActionPreference = $false
18	$root = Split-Path $PSScriptRoot -Parent
19	if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
20	$scrapeJsPath = Join-Path $root 'scripts\scrape-products-page.js'
21	$clickNextJsPath = Join-Path $root 'scripts\products-click-next.js'
22	if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
23	if (-not (Test-Path $scrapeJsPath)) { throw "Missing $scrapeJsPath" }
24	$clickNextJs = ''
25	if (Test-Path $clickNextJsPath) { $clickNextJs = Get-Content $clickNextJsPath -Raw -Encoding UTF8 }
26	
27	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
28	$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
29	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
30	if (Test-Path $qingquanLib) { . $qingquanLib }
31	
32	$script:logsDir = Join-Path $root 'logs'
33	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
34	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
35	$script:runLogFile = Join-Path $script:logsDir ("products-run-{0}.log" -f $script:runStamp)
36	
37	function Write-RunLog([string]$msg) {
38	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
39	  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
40	}
41	function Write-Step([string]$msg) {
42	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
43	  Write-RunLog $msg
44	}
45	
46	function ConvertTo-ProcessArgument([string]$s) {
47	  if ($null -eq $s) { return '""' }
48	  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
49	  return $s
50	}
51	
52	function Initialize-ZiniaoCli {
53	  if ($script:ZiniaoNode) { return }
54	  $node = (Get-Command node -ErrorAction SilentlyContinue).Source
55	  if (-not $node) { throw 'node not found' }
56	  $runJs = Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
57	  if (-not (Test-Path $runJs)) {
58	    $cmd = Get-Command ziniao -ErrorAction SilentlyContinue
59	    if ($cmd) { $runJs = $cmd.Source }
60	  }
61	  if (-not (Test-Path $runJs)) { throw 'ziniao-cli run.js not found' }
62	  $script:ZiniaoNode = $node
63	  $script:ZiniaoRunJs = $runJs
64	}
65	
66	function Invoke-Ziniao([string[]]$CliArgs) {
67	  Initialize-ZiniaoCli
68	  $utf8 = [System.Text.UTF8Encoding]::new($false)
69	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
70	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
71	  $psi = New-Object System.Diagnostics.ProcessStartInfo
72	  $psi.FileName = $script:ZiniaoNode
73	  $psi.Arguments = $argLine
74	  $psi.UseShellExecute = $false
75	  $psi.RedirectStandardOutput = $true
76	  $psi.RedirectStandardError = $true
77	  $psi.CreateNoWindow = $true
78	  $psi.StandardOutputEncoding = $utf8
79	  $psi.StandardErrorEncoding = $utf8
80	  $p = New-Object System.Diagnostics.Process
81	  $p.StartInfo = $psi
82	  [void]$p.Start()
83	  $stdout = $p.StandardOutput.ReadToEnd()
84	  $stderr = $p.StandardError.ReadToEnd()
85	  $p.WaitForExit()
86	  if ($stderr) { Write-Host $stderr }
87	  # 合并 stderr：Bridge 错误有时只在 stderr 的 JSON 里，stdout 为空
88	  if ([string]::IsNullOrWhiteSpace($stdout) -and $stderr -and ($stderr -match '\{')) {
89	    return $stderr
90	  }
91	  if ($stdout -and $stderr -and ($stderr -match '无法连接紫鸟浏览器 Bridge') -and ($stdout -notmatch '无法连接')) {
92	    return ($stdout + "`n" + $stderr)
93	  }
94	  return $stdout
95	}
96	
97	function ConvertTo-ScrapeOneLine([string]$js) {
98	  $one = ($js -replace '(?m)^\s*//.*$', '' -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
99	  return $one
100	}
101	
102	function Get-ProductsUrl($store, $cfg) {
103	  $plat = ''
104	  if ($store.platformName) { $plat = [string]$store.platformName }
105	  elseif ($store.platform) { $plat = [string]$store.platform }
106	  if ($cfg.productUrl -and $cfg.productUrl.byPlatform -and $plat) {
107	    foreach ($p in $cfg.productUrl.byPlatform.PSObject.Properties) {
108	      if ($plat -eq [string]$p.Name -or $plat -like ("*{0}*" -f $p.Name) -or ([string]$p.Name -like ("*{0}*" -f $plat))) {
109	        return [string]$p.Value
110	      }
111	    }
112	  }
113	  if ($cfg.productUrl -and $cfg.productUrl.default) { return [string]$cfg.productUrl.default }
114	  if ($cfg.urls -and $cfg.urls.orders) { return [string]$cfg.urls.orders }
115	  return 'https://seller-uk.tiktok.com/product/manage'
116	}
117	
118	function Get-DisplayName($store, $map) {
119	  $n = [string]$store.storeName
120	  if ($map -and $map.PSObject.Properties.Name -contains $n) { return [string]$map.$n }
121	  return $n
122	}
123	
124	function Get-ScrapePayload([string]$execOut) {
125	  if ([string]::IsNullOrWhiteSpace($execOut)) { return $null }
126	  # ziniao wraps result JSON in data.data.result string sometimes
127	  try {
128	    $j = $execOut | ConvertFrom-Json
129	    if ($j.data -and $j.data.data -and $j.data.data.result) {
130	      $inner = [string]$j.data.data.result
131	      return ($inner | ConvertFrom-Json)
132	    }
133	    if ($j.ok -ne $null -and $j.rows) { return $j }
134	    if ($j.ok -ne $null) { return $j }
135	  } catch { }
136	  # last {...} object in output
137	  $m = [regex]::Matches($execOut, '\{(?:[^{}]|(?<o>\{)|(?<-o>\}))+(?(o)(?!))\}')
138	  if ($m.Count -gt 0) {
139	    try { return ($m[$m.Count - 1].Value | ConvertFrom-Json) } catch { }
140	  }
141	  return $null
142	}
143	
144	function Test-ZiniaoBridgeError([string]$out) {
145	  # 注意：ziniao 成功提示常走 stderr，Invoke-Ziniao 只返回 stdout → 空串≠Bridge 挂
146	  if ([string]::IsNullOrWhiteSpace($out)) { return $false }
147	  if ($out -match '无法连接紫鸟浏览器 Bridge|无法连接.*9481') { return $true }
148	  try {
149	    $j = $out | ConvertFrom-Json
150	    if ($j.ok -eq $false -and $j.error) {
151	      $msg = "$($j.error.message)$($j.error.hint)$($j.error.type)"
152	      if ($msg -match 'Bridge|9481|无法连接紫鸟') { return $true }
153	    }
154	  } catch { }
155	  return $false
156	}
157	
158	function Test-ZiniaoCliFailed([string]$out) {
159	  if ([string]::IsNullOrWhiteSpace($out)) { return $false }
160	  if (Test-ZiniaoBridgeError $out) { return $true }
161	  try {
162	    $j = $out | ConvertFrom-Json
163	    if ($j.ok -eq $false) { return $true }
164	  } catch { }
165	  return $false
166	}
167	
168	function Wait-ZiniaoBridgeReady([int]$MaxSec = 60) {
169	  $deadline = (Get-Date).AddSeconds($MaxSec)
170	  while ((Get-Date) -lt $deadline) {
171	    $portUp = $false
172	    try {
173	      $tnc = Test-NetConnection -ComputerName '127.0.0.1' -Port 9481 -WarningAction SilentlyContinue
174	      if ($tnc -and $tnc.TcpTestSucceeded) { $portUp = $true }
175	    } catch {
176	      try {
177	        $c = New-Object System.Net.Sockets.TcpClient
178	        $iar = $c.BeginConnect('127.0.0.1', 9481, $null, $null)
179	        $portUp = $iar.AsyncWaitHandle.WaitOne(1500, $false) -and $c.Connected
180	        $c.Close()

