function Open-ProductStore([string]$sid, [string]$productUrl, $cfg, [int]$waitOpenMs) {
  # 关键：open 时已带 launchUrl=product/manage。
  # 实探测：page visit 商品页常把 Bridge 打挂（9481 TCP 仍通但 HTTP 失败）；
  # 订单 visit 正常。因此商品链路默认 **跳过 visit**，只靠 open + 长等待 + exec。
  $openArgs = @('store', 'open', '--id', $sid, '--url', $productUrl)
  if ($cfg.options.windowRatio -and $cfg.options.windowRatio -ne 'none') {
    $openArgs += @('--window-ratio', [string]$cfg.options.windowRatio)
  }
  $openArgsLocal = $openArgs
  $openOut = Invoke-Ziniao $openArgsLocal
  Write-Host $openOut
  # open 后 Bridge 常抖 20–60s：先硬等，再轮询 warm，避免过早 reopen
  $settle = [Math]::Max($waitOpenMs, 50000)
  Write-Step ("  open done — settle {0}ms (no page visit; product manage Bridge quirk)..." -f $settle)
  Start-Sleep -Milliseconds $settle

  $warmJs = 'JSON.stringify({ok:true,href:String(location.href||""),tables:document.querySelectorAll("table").length,tlen:((document.body&&document.body.innerText)||"").length})'
  $href = ''
  $tables = 0
  $tlen = 0
  $warmOk = $false
  $maxWarm = 8
  for ($wi = 1; $wi -le $maxWarm; $wi++) {
    [void](Wait-ZiniaoBridgeReady -MaxSec 20)
    $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
    if (Test-ZiniaoBridgeError $warm) {
      Write-Step ("  warm {0}/{1}: Bridge busy — wait 12s" -f $wi, $maxWarm)
      Start-Sleep -Seconds 12
      continue
    }
    $warmPayload = Get-ScrapePayload $warm
    $href = ''; $tables = 0; $tlen = 0
    if ($warmPayload) {
      if ($warmPayload.href) { $href = [string]$warmPayload.href }
      if ($null -ne $warmPayload.tables) { $tables = [int]$warmPayload.tables }
      if ($null -ne $warmPayload.tlen) { $tlen = [int]$warmPayload.tlen }
    }
    Write-Step ("  warm {0}/{1} href={2} tables={3} tlen={4}" -f $wi, $maxWarm, $(if ($href) { $href } else { '(empty)' }), $tables, $tlen)
    if ($href -and $href -ne 'about:blank' -and ($tables -gt 0 -or $tlen -gt 200)) {
      $warmOk = $true
      break
    }
    if ($href -and $href -ne 'about:blank' -and $tlen -gt 50) {
      # 页在但表未出：再等 SPA
      Write-Step '  page present but thin — wait 15s for table'
      Start-Sleep -Seconds 15
      $warmOk = $true
      break
    }
    Start-Sleep -Seconds 10
  }

  if (-not $warmOk) {
    Write-Step '  warm never ready — close/reopen once then poll again'
    try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
    Start-Sleep -Seconds 5
    Write-Host (Invoke-Ziniao $openArgsLocal)
    Start-Sleep -Milliseconds ([Math]::Max($settle, 55000))
    for ($wi = 1; $wi -le 5; $wi++) {
      [void](Wait-ZiniaoBridgeReady -MaxSec 15)
      $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
      if (Test-ZiniaoBridgeError $warm) { Start-Sleep -Seconds 10; continue }
      $wp = Get-ScrapePayload $warm
      if ($wp -and $wp.href -and [string]$wp.href -ne 'about:blank') {
        Write-Step ("  re-warm ok href={0} tables={1}" -f $wp.href, $(if ($null -ne $wp.tables) { $wp.tables } else { '?' }))
        break
      }
      Start-Sleep -Seconds 10
    }
  }
}

