input.command:
$path = 'E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\scripts\run-products.ps1'
$tokens = $null
$errors = $null
$ast = [System.Management.Automation.Language.Parser]::ParseFile($path, [ref]$tokens, [ref]$errors)
if ($errors -and $errors.Count -gt 0) {
  $errors | ForEach-Object { Write-Host $_.ToString() }
  exit 1
}
Write-Host "PS parse OK"
# unit-test URL helpers by dot-sourcing only the functions via a tiny harness
$harness = @'
function Test-IsProductManageUrl([string]$href) {
  if ([string]::IsNullOrWhiteSpace($href)) { return $false }
  if ($href -eq 'about:blank') { return $false }
  if ($href -match '(?i)/product/manage') { return $true }
  if ($href -match '(?i)/product/(list|manage|all)') { return $true }
  return $false
}
function Test-IsForbiddenNonProductUrl([string]$href) {
  if ([string]::IsNullOrWhiteSpace($href)) { return $false }
  if ($href -match '(?i)/order(\?|/|$)|[?&]tab=all') { return $true }
  if ($href -match '(?i)/health-center|/finance/|/homepage|/ads-creation|/compass|/creator') { return $true }
  return $false
}
$cases = @(
  @{u='https://seller-uk.tiktok.com/product/manage?shop_region=GB'; p=$true; f=$false},
  @{u='https://seller-uk.tiktok.com/order?selected_sort=6&tab=all'; p=$false; f=$true},
  @{u='https://seller-uk.tiktok.com/health-center'; p=$false; f=$true},
  @{u='about:blank'; p=$false; f=$false},
  @{u='https://seller.eu.tiktokshopglobalselling.com/product/manage'; p=$true; f=$false}
)
foreach ($c in $cases) {
  $pp = Test-IsProductManageUrl $c.u
  $ff = Test-IsForbiddenNonProductUrl $c.u
  if ($pp -ne $c.p -or $ff -ne $c.f) { throw "FAIL $($c.u) product=$pp/$($c.p) forb=$ff/$($c.f)" }
  Write-Host "OK $($c.u)"
}
'@
Invoke-Expression $harness

