input.command:
cd "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads"
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$out = "logs\deal-products-gate-out-$stamp.log"
$err = "logs\deal-products-gate-err-$stamp.log"
Write-Host "Deal products with page gate + timeout 120 -> $out"
$p = Start-Process -FilePath powershell.exe -ArgumentList @(
  '-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass',
  '-File','.\scripts\run-products.ps1',
  '-ConfigPath',(Resolve-Path '.\config\stores.config.deal-only.json').Path,
  '-DryRun','false'
) -WorkingDirectory (Get-Location).Path -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err
Write-Host "pid=$($p.Id)"
$deadline = (Get-Date).AddMinutes(35)
while ((Get-Date) -lt $deadline -and -not $p.HasExited) {
  Start-Sleep -Seconds 25
  $sz = if (Test-Path $out) { (Get-Item $out).Length } else { 0 }
  $last = if (Test-Path $out) { (Get-Content $out -Tail 1 -Encoding UTF8) } else { '' }
  Write-Host ("[{0}] size={1} | {2}" -f (Get-Date -Format HH:mm:ss), $sz, $last)
}
if (-not $p.HasExited) {
  Write-Host "TIMEOUT still running - dump tail"
  Get-Content $out -Tail 40 -Encoding UTF8
  exit 1
}
Write-Host "exit=$($p.ExitCode)"
Get-Content $out -Tail 80 -Encoding UTF8
Get-ChildItem logs\products-summary-*.json | Sort-Object LastWriteTime -Descending | Select-Object -First 1 | ForEach-Object {
  Write-Host "SUMMARY $($_.Name)"
  Get-Content $_.FullName -Raw -Encoding UTF8
}

# Server verification via login + shops + re-ingest probes
$base = "https://qingquan.jmzlai.com"
$key = "2badba5de266ed9c749307ddb252b8a5"

# 1) login if admin known from .env
$loginBody = @{ username = "admin"; password = "admin123" } | ConvertTo-Json -Compress
try {
  $login = Invoke-RestMethod -Method POST -Uri "$base/api/v1/auth/login" -ContentType "application/json" -Body ([Text.Encoding]::UTF8.GetBytes($loginBody)) -TimeoutSec 20
  "login OK keys=$($login.PSObject.Properties.Name -join ',')"
  $token = $login.access_token
  if (-not $token) { $token = $login.token }
} catch {
  "login FAIL: $($_.Exception.Message) $($_.ErrorDetails.Message)"
  $token = $null
}

if ($token) {
  $auth = @{ Authorization = "Bearer $token" }
  try {
    $me = Invoke-RestMethod -Uri "$base/api/v1/auth/me" -Headers $auth -TimeoutSec 15
    "me: $($me | ConvertTo-Json -Compress)"
  } catch { "me fail: $($_.Exception.Message)" }
  try {
    $shops = Invoke-RestMethod -Uri "$base/api/v1/shops" -Headers $auth -TimeoutSec 20
    "shops type=$($shops.GetType().Name)"
    if ($shops -is [array]) {
      $shops | Where-Object { $_.platform -eq 'tiktok' -or $_.name -match 'Deal|Gardena|Pop|TikTok' } | ForEach-Object {
        "shop id=$($_.id) name=$($_.name) ext=$($_.external_shop_id) platform=$($_.platform)"
      }
    } elseif ($shops.items) {
      $shops.items | ForEach-Object { "shop $($_.name) $($_.external_shop_id) $($_.platform)" }
    } else {
      $shops | ConvertTo-Json -Depth 4 -Compress
    }
  } catch { "shops fail: $($_.Exception.Message) $($_.ErrorDetails.Message)" }
}

# 2) Ingest probe: known Deal product from last debug sample -> expect dup
cd "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads"
. .\scripts\qingquan-client.ps1
$cfg = Get-Content .\config\stores.config.json -Raw -Encoding UTF8 | ConvertFrom-Json
$cfg.qingquan.timeoutSec = 120
$dbg = Get-Content .\logs\products-debug-27501502216807-20260804-090336.json -Raw -Encoding UTF8 -ErrorAction SilentlyContinue | ConvertFrom-Json
if (-not $dbg) {
  # fallback any deal debug
  $f = Get-ChildItem .\logs\products-debug-27501502216807-*.json | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  $dbg = Get-Content $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
  "using debug $($f.Name)"
}
$sample = @($dbg.sampleRows)[0]
"probe productId=$($sample.productId) name=$($sample.productName.Substring(0,[Math]::Min(40,$sample.productName.Length)))"
$row = [pscustomobject]@{
  productId = $sample.productId
  productName = $sample.productName
  sellerSku = $sample.sellerSku
  status = $sample.status
  stockQty = $sample.stockQty
  price = $sample.price
  salesQty = $sample.salesQty
  currencyHint = $sample.currencyHint
}
$items = ConvertTo-QingquanProductIngestItems -Rows @($row) -CollectedAt ((Get-Date).ToUniversalTime().ToString('o')) -StoreId '27501502216807' -StoreName 'Deal to deal' -Currency 'GBP' -SourceUrl 'https://seller-uk.tiktok.com/product/manage?shop_region=GB'
$r = Send-QingquanIngest -Config $cfg -Items $items -Source 'tiktok_products'
"product probe ok=$($r.ok) accepted=$($r.accepted) dup=$($r.duplicated) failed=$($r.failed) err=$($r.error)"

# 3) order smoke: re-send one order idempotency if we have debug
$od = Get-ChildItem .\logs\orders-debug-27501502216807-*.json -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($od) {
  "orders debug: $($od.Name) size=$($od.Length)"
}

# 4) ads probe - send tiny known campaign if multi-store log exists
# heartbeat already works
$h = @{ "X-Api-Key" = $key; "Content-Type" = "application/json; charset=utf-8" }
$hb = Invoke-RestMethod -Method POST -Uri "$base/api/v1/collectors/heartbeat" -Headers $h -Body ([Text.Encoding]::UTF8.GetBytes((@{ node_id = "verify-pc"; version = "gate-fix" } | ConvertTo-Json -Compress))) -TimeoutSec 15
"heartbeat $($hb | ConvertTo-Json -Compress)"

# richer shops dump
$base = "https://qingquan.jmzlai.com"
$login = Invoke-RestMethod -Method POST -Uri "$base/api/v1/auth/login" -ContentType "application/json" -Body ([Text.Encoding]::UTF8.GetBytes((@{username='admin';password='admin123'}|ConvertTo-Json -Compress))) -TimeoutSec 20
$auth = @{ Authorization = "Bearer $($login.access_token)" }
$shops = Invoke-RestMethod -Uri "$base/api/v1/shops" -Headers $auth -TimeoutSec 20
$shops | ConvertTo-Json -Depth 5 | Select-Object -First 1
# try export dry_run tk if supported on server (may 422)
try {
  $body = @{ table_key='tk_ads_campaign'; mode='incremental'; lookback_days=14; limit=5; dry_run=$true; run_inline=$true } | ConvertTo-Json -Compress
  $r = Invoke-RestMethod -Method POST -Uri "$base/api/v1/export/feishu" -Headers ($auth + @{'Content-Type'='application/json'}) -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 60
  "export dry: $($r | ConvertTo-Json -Depth 6 -Compress)"
} catch { "export dry fail: $($_.Exception.Message) $($_.ErrorDetails.Message)" }

